// Authored communicative syllabus. Each row teaches one focus, not an entire level.
// CEFR is a scope reference, not a claim of certified spoken proficiency.
const syllabi={};
const unit=(title,goal,words,story,rows)=>({title,goal,words,story,rows:rows.trim().split('\n').map(line=>line.split('|'))});
syllabi.A2=[
unit('Lo que pasó','Contar hechos terminados y preguntar por ellos.','weekend:fin de semana;journey:trayecto;ticket:billete;receipt:recibo;queue:fila',
['Maya visited a small town on Saturday. She travelled by train because her car was at the garage. She bought a return ticket. The museum was closed, so she walked around the market instead.','¿Por qué fue en tren?','Su coche estaba en el taller','Quería visitar el aeropuerto','No existía una carretera'],`
Regular past|Usa pasado simple para un hecho terminado. Los regulares añaden -ed; no añadas -ed después de did.|Maya visited the market yesterday.|Maya visitó el mercado ayer.|visited|visits|visiting
Irregular past|Algunos pasados cambian de forma: go pasa a went. Aprende la forma dentro de una experiencia, no como una regla con -ed.|We went to the beach last Sunday.|Fuimos a la playa el domingo pasado.|went|goed|go
Past negatives|La negación del pasado es didn't más verbo base. El auxiliar lleva el pasado; el verbo principal no vuelve a cambiar.|I didn't buy a ticket yesterday.|No compré un billete ayer.|buy|bought|buying
Past questions|Para preguntar por una acción terminada usa Did más sujeto más verbo base. Was y were forman sus preguntas sin did.|Did you visit your family last week?|¿Visitaste a tu familia la semana pasada?|visit|visited|visiting`),
unit('Historias sencillas','Ordenar acontecimientos y describir el contexto.','storm:tormenta;noise:ruido;street:calle;message:mensaje;moment:momento',
['Noah was walking home when it started to rain. He went into a café and called his sister. First he ordered tea, then he sent her the address. She arrived twenty minutes later.','¿Dónde esperó Noah?','En un café','En un aeropuerto','En la oficina'],`
Past continuous|Was o were más verbo con -ing describe una acción en desarrollo en un momento pasado. No lo uses para toda acción terminada.|I was reading when you called.|Estaba leyendo cuando llamaste.|was reading|readed|am read
Interrupted actions|Combina pasado continuo para el contexto y pasado simple para lo que lo interrumpe. When introduce aquí el acontecimiento breve.|We were cooking when the lights went out.|Estábamos cocinando cuando se fue la luz.|were cooking|was cooking|are cook
Sequence a story|First, then y finally orientan a quien escucha. Usa finalmente para el cierre, sin cambiar los tiempos a mitad de la historia sin motivo.|First we checked the address, then we left.|Primero comprobamos la dirección y después salimos.|then|because of|although of
Used to|Used to más verbo base habla de hábitos pasados que ya no son actuales. No confundas used to con usually, que expresa frecuencia.|I used to live near the station.|Antes vivía cerca de la estación.|used to|use for|am used`),
unit('Planes y decisiones','Distinguir intención, decisión y acuerdo.','appointment:cita;forecast:pronóstico;invitation:invitación;calendar:calendario;arrangement:acuerdo',
['Lina has booked a table for Friday evening. She is meeting two friends at seven. The forecast says it will rain, so they plan to eat indoors. She has already sent everyone the restaurant address.','¿Dónde planean comer?','Dentro del restaurante','En un parque','En un tren'],`
Going to|Be going to más verbo base expresa una intención previa. Cambia be con la persona; no elimines am, is o are.|I am going to study tonight.|Voy a estudiar esta noche.|am going to|going to|am go to
Will decisions|Will más verbo base permite tomar una decisión en ese momento. No añadas -s después de will ni uses to delante del verbo.|The phone is ringing. I will answer it.|Suena el teléfono. Yo contestaré.|will answer|will to answer|will answers
Present arrangements|El presente continuo puede expresar una cita futura acordada. Añade una referencia temporal que distinga el plan de lo que ocurre ahora.|We are meeting the client tomorrow.|Nos reunimos con el cliente mañana.|are meeting|is meeting|are meet
First conditional|If más presente y will más verbo base relaciona una condición futura posible con su consecuencia. No pongas will en ambas partes.|If it rains, we will stay at home.|Si llueve, nos quedaremos en casa.|rains|will rains|raining`),
unit('Experiencias recientes','Relacionar experiencias con el presente.','experience:experiencia;abroad:en el extranjero;already:ya;yet:todavía;recently:recientemente',
['Omar has just returned from Peru. He has tried several local dishes, but he has not visited the coast yet. Last Tuesday he explored a mountain village. He wants to return next year.','¿Qué no ha visitado aún?','La costa','Un pueblo de montaña','Perú'],`
Have you ever|Have o has más participio expresa experiencia sin fecha terminada. Ever pregunta si ocurrió alguna vez; no significa siempre.|Have you ever travelled abroad?|¿Has viajado alguna vez al extranjero?|travelled|travel|travelling
Already and yet|Already suele ir antes del participio. Yet aparece normalmente al final de preguntas o negaciones sobre algo esperado.|I haven't finished the report yet.|Todavía no he terminado el informe.|yet|already not|ever not
Perfect or past|Usa pasado simple con yesterday o una fecha terminada. Usa presente perfecto cuando conectas la experiencia con el presente sin esa fecha.|She visited Lima last year.|Ella visitó Lima el año pasado.|visited|has visited|has visit
For and since|For introduce duración; since introduce el punto inicial. No traduzcas desde hace usando since delante de una cantidad de años.|We have lived here for two years.|Llevamos dos años viviendo aquí.|for|since|during of`),
unit('Comparar y elegir','Tomar decisiones sobre productos y lugares.','price:precio;quality:calidad;size:talla o tamaño;choice:elección;discount:descuento',
['Two hotels have rooms available. The central hotel is cheaper, but its rooms are smaller. The hotel near the park includes breakfast and is quieter. Ava chooses the park hotel because she needs to sleep well.','¿Qué prioriza Ava?','Dormir bien','La habitación más barata','Estar junto al aeropuerto'],`
Comparatives|Usa -er con muchos adjetivos cortos y more con los largos. Introduce la segunda opción con than; no combines more y cheaper.|This room is cheaper than that one.|Esta habitación es más barata que aquella.|cheaper than|more cheaper that|cheap that
Superlatives|The más superlativo destaca un elemento dentro de un grupo. Para adjetivos largos usa the most; evita the most cheapest.|This is the most comfortable chair.|Esta es la silla más cómoda.|most comfortable|more comfortable|comfortablest
As as|As más adjetivo más as expresa igualdad. En negativo indica que no se alcanza el mismo grado, sin crear un comparativo con -er.|The bus isn't as fast as the train.|El autobús no es tan rápido como el tren.|as fast as|as faster as|so faster than
Too and enough|Too indica exceso para un fin. Enough expresa suficiencia y va después del adjetivo: big enough, no enough big.|This bag is big enough for my laptop.|Este bolso es lo bastante grande para mi portátil.|big enough|enough big|too enough`),
unit('Salud y obligaciones','Pedir ayuda y explicar necesidades.','pain:dolor;rest:descanso;medicine:medicamento;rule:norma;permission:permiso',
['Ben has a sore throat and a headache. The pharmacist tells him to rest and read the instructions on the packet. He must not take more than the stated dose. He calls work to explain that he is unwell.','¿Qué debe consultar Ben?','Las instrucciones del envase','El horario del tren','La carta del restaurante'],`
Should advice|Should más verbo base da un consejo, no una obligación. Para negar usa shouldn't. Un consejo lingüístico sobre salud no sustituye atención médica.|You should ask for help.|Deberías pedir ayuda.|should ask|should to ask|should asks
Have to|Have to más verbo base expresa una obligación. En tercera persona usa has to; la pregunta lleva do o does.|She has to arrive before nine.|Ella tiene que llegar antes de las nueve.|has to|have to|must to
Mustn't or don't have to|Mustn't expresa prohibición; don't have to indica que no es necesario. Confundirlas cambia por completo lo que permites.|You don't have to print the ticket; a phone is fine.|No tienes que imprimir el billete; el teléfono sirve.|don't have to|mustn't|can't to
Could requests|Could you más verbo base suaviza una petición. No uses could you to ni conviertas toda petición cortés en una afirmación.|Could you help me with this form?|¿Podrías ayudarme con este formulario?|help|to help|helping`),
unit('En viaje','Resolver necesidades fuera de casa.','reservation:reserva;luggage:equipaje;platform:andén;delay:retraso;connection:conexión',
['A train to Bristol has been delayed. The next service leaves from platform six, not four. Passengers with reservations can use the later train without buying another ticket. Staff ask them to keep their original tickets.','¿De qué andén sale el siguiente tren?','Del seis','Del cuatro','Del dos'],`
Indirect questions|Después de Could you tell me usa orden de afirmación en la pregunta incluida. Evita duplicar la inversión del sujeto.|Could you tell me where the station is?|¿Podría decirme dónde está la estación?|the station is|is the station|does station
Some and any|Usa some en muchas afirmaciones y ofrecimientos; any en muchas preguntas o negaciones. Considera el sentido, no solo el signo de pregunta.|We don't have any luggage.|No tenemos equipaje.|any|a|many of
How much and how many|How much pregunta cantidad de un incontable; how many, número de contables en plural. Luggage no suele admitir un plural con -s.|How much luggage can I take?|¿Cuánto equipaje puedo llevar?|much|many|a few
Clarify a detail|Comprueba una información repitiendo el dato y pidiendo confirmación. Esta estrategia evita fingir que entendiste todo el anuncio.|Did you say platform six?|¿Dijo andén seis?|say|said|saying`),
unit('Personas y relaciones','Describir y conectar ideas sobre personas.','neighbour:vecino;colleague:colega;advice:consejo;invitation:invitación;hobby:afición',
['Ella has a new colleague who works remotely. They both enjoy hiking, although Ella prefers short walks. She invites him to a weekend trip, but he has to help his neighbour on Saturday. They agree to meet on Sunday instead.','¿Qué día acuerdan verse?','El domingo','El sábado','El viernes'],`
Who and which|Who conecta una persona con información que la identifica. Which se usa para cosas. No añadas otro sujeto que repita who.|My colleague is the person who called you.|Mi colega es la persona que te llamó.|who|which|where
Because and so|Because introduce la causa; so introduce el resultado. No las intercambies ni unas las dos para la misma conexión simple.|I stayed home because I was tired.|Me quedé en casa porque estaba cansado.|because|so|but of
Although|Although introduce un contraste que resulta inesperado. Evita duplicarlo con but en la oración principal.|Although it was cold, we went for a walk.|Aunque hacía frío, salimos a caminar.|Although|Because of|Despite of
Object pronouns|Usa me, him, her, us o them como complemento. Después de una preposición también necesitas esa forma: with them.|I sent them an invitation.|Les envié una invitación.|them|they|their`),
unit('Tu trabajo diario','Comunicar avances y resolver problemas básicos.','task:tarea;deadline:fecha límite;issue:problema;update:actualización;meeting:reunión',
['The team has finished the login page, but the email service is not working. Sara is checking the settings. She needs help from a colleague before the afternoon meeting. The deadline is Friday, so there is still time to test.','¿Qué necesita Sara antes de la reunión?','Ayuda de un colega','Comprar un billete','Cambiar de oficina'],`
Work now or usually|Usa presente simple para la rutina y continuo para una tarea temporal en curso. Un proyecto de hoy no es necesariamente tu hábito habitual.|I usually test APIs, but today I am writing documentation.|Normalmente pruebo APIs, pero hoy estoy escribiendo documentación.|am writing|write always|writing am
Report recent progress|Have o has más participio conecta una tarea terminada con el estado actual. No omitas el auxiliar al comunicar un avance.|We have fixed the login issue.|Hemos solucionado el problema de acceso.|have fixed|has fixed|have fix
Explain a problem|It sustituye una cosa singular; them sustituye varias. Nombra primero el referente para que la otra persona sepa de qué hablas.|The API is slow. We need to check it.|La API es lenta. Necesitamos revisarla.|it|them|its
Ask for support|Can o could más verbo base permite pedir una acción concreta. Añade el objeto o contexto para que la petición resulte útil.|Could you check the error message with me?|¿Podrías revisar el mensaje de error conmigo?|check|checked|to check`),
unit('Ya puedo resolverlo','Integrar pasado, planes y comunicación.','solution:solución;reason:motivo;plan:plan;reply:respuesta;detail:detalle',
['Leo missed a call from a client yesterday. He has read the message and is going to call back after lunch. The client wants to change a delivery date. Leo will check the schedule before he promises anything.','¿Qué hará antes de prometer un cambio?','Consultar el calendario','Cancelar el pedido','Comprar otro teléfono'],`
Invitations|Would you like to más verbo base invita a hacer algo. Para aceptar, una respuesta breve y amable es suficiente; no necesitas traducir toda la cortesía literalmente.|Would you like to join us for lunch?|¿Te gustaría acompañarnos a almorzar?|to join|joining|join to
Offer an alternative|Could más verbo base propone una posibilidad. Explica una opción concreta cuando rechazas una hora o un lugar.|We could meet on Tuesday instead.|Podríamos reunirnos el martes en su lugar.|could meet|could to meet|could meeting
Confirm an agreement|Comprueba quién hará qué y cuándo. Las referencias de tiempo y el sujeto explícito importan más que una respuesta vaga como yes.|I will send the details before Friday.|Enviaré los detalles antes del viernes.|will send|will sent|will sending
Reflect and continue|Usa preguntas con do para valorar lo que entiendes ahora y con did para una experiencia terminada. Elige el tiempo según el significado.|What did you learn from the trip?|¿Qué aprendiste del viaje?|did you learn|you did learn|did you learned`)
];
syllabi.B1=[
unit('Experiencias que cuentan','Narrar experiencias y explicar su importancia.','achievement:logro;challenge:reto;opportunity:oportunidad;skill:habilidad;confidence:confianza',
['I have worked with several teams since I left college. Last year I joined a community project and learned to explain technical ideas to beginners. The hardest part was listening before offering solutions. That experience changed how I work with people.','¿Qué cambió su forma de trabajar?','Un proyecto comunitario','Una compra por internet','Una cancelación de viaje'],`
Experience and detail|Present perfect abre una experiencia; pasado simple cuenta cuándo ocurrió. No uses una fecha terminada con have done.|I have led a team, but I started as a volunteer.|He dirigido un equipo, pero empecé como voluntario.|have led|have lead|has led
Since a starting point|Since presenta un punto inicial; for presenta duración. Compara desde 2020 con durante dos años.|I have worked here since 2020.|Trabajo aquí desde 2020.|since|for|during
Still developing|Have been más -ing destaca una actividad que continúa o su duración. No lo confundas con una cantidad ya completada.|We have been learning together for months.|Llevamos meses aprendiendo juntos.|have been learning|have learning|has been learn
Describe an achievement|Been es el participio de be. Una experiencia profesional puede explicarse sin exagerar su alcance ni añadir una fecha inexistente.|This has been my biggest challenge so far.|Este ha sido mi mayor reto hasta ahora.|has been|has was|have be`),
unit('Contar una historia','Conectar contexto, hechos y consecuencias.','background:contexto;incident:incidente;discovery:descubrimiento;relief:alivio;memory:recuerdo',
['We were waiting for a bus when we noticed a lost bag. Its owner had already left. A number inside helped us contact her. By the time she returned, we had taken the bag to the station office. She was relieved that nothing was missing.','¿Cómo localizaron a la dueña?','Con un número dentro del bolso','Mediante un anuncio de televisión','Porque esperó junto al autobús'],`
Earlier past|Had más participio sitúa un hecho antes de otro momento pasado. No lo uses solo para que una historia suene más formal.|She had left before I arrived.|Ella se había ido antes de que yo llegara.|had left|has leave|had leave
When and while|While suele presentar una acción en desarrollo. El pasado simple puede introducir el hecho que cambia esa situación.|While I was waiting, I checked the message.|Mientras esperaba, revisé el mensaje.|was waiting|waited was|am waiting
Relative detail|Whose expresa posesión en una oración relativa. No equivale a who's, que contrae who is o who has.|We helped a traveller whose bag was missing.|Ayudamos a una viajera cuyo bolso se había perdido.|whose|who's|which
Narrative result|By the time conecta un momento de referencia con algo ya ocurrido. Elige had más participio para la acción anterior.|By the time we arrived, the shop had closed.|Cuando llegamos, la tienda ya había cerrado.|had closed|has closed|had close`),
unit('Opiniones con razones','Dar una opinión y escuchar otra postura.','viewpoint:punto de vista;reason:razón;evidence:evidencia;benefit:beneficio;drawback:inconveniente',
['Our neighbourhood is discussing a new cycle lane. Some residents expect safer journeys, while others worry about deliveries. I support the plan provided that shops can still receive goods. We should test it for a month and listen to the people affected.','¿Qué propone antes de decidir definitivamente?','Una prueba de un mes','Cerrar todas las tiendas','Eliminar los repartos'],`
Give a reason|In my view presenta una opinión, no un hecho probado. Añade because y una razón que la otra persona pueda considerar.|In my view, the plan is useful because it saves time.|En mi opinión, el plan es útil porque ahorra tiempo.|because|despite|although of
Agree partly|Although permite reconocer un punto antes de discrepar. No añadas but a la misma estructura de contraste.|Although I see your point, I disagree with the conclusion.|Aunque entiendo tu punto, no estoy de acuerdo con la conclusión.|Although|Despite of|Because of
Compare options|Whereas contrasta dos hechos o preferencias. Mantén dos oraciones completas para que la comparación resulte clara.|The train is faster, whereas the bus is cheaper.|El tren es más rápido, mientras que el autobús es más barato.|whereas|because of|despite of
Support a suggestion|Should más verbo base propone una recomendación. Acompáñala de una razón y deja espacio a alternativas.|We should test the idea before we decide.|Deberíamos probar la idea antes de decidir.|should test|should to test|should testing`),
unit('Posibilidades','Distinguir lo posible de lo imaginario.','possibility:posibilidad;condition:condición;risk:riesgo;decision:decisión;consequence:consecuencia',
['If the weather stays dry, we will walk to the lake. If it rains, we can visit the science museum instead. I would choose the lake if I had the final say, but everyone should have a chance to suggest something.','¿Qué harán si llueve?','Visitar el museo','Caminar al lago sin cambiar el plan','Cancelar toda la semana'],`
Real conditions|If más presente plantea una condición futura posible. La consecuencia puede llevar will, can o una instrucción.|If we leave now, we will catch the train.|Si salimos ahora, alcanzaremos el tren.|leave|will leave|left would
Imaginary present|If más pasado y would más verbo base imagina una situación distinta. Ese pasado no indica necesariamente tiempo pasado.|If I had more time, I would travel more.|Si tuviera más tiempo, viajaría más.|would travel|will travelled|would to travel
Unless|Unless significa si no o a menos que. Evita una segunda negación que cambie la condición sin querer.|We won't leave unless everyone is ready.|No saldremos a menos que todos estén listos.|unless|despite|because of
Might for possibility|Might más verbo base indica posibilidad sin certeza. No expresa una promesa ni requiere to.|The client might change the deadline.|El cliente podría cambiar la fecha límite.|might change|might to change|might changes`),
unit('Explicar procesos','Describir cómo se hace algo sin perder al oyente.','step:paso;instruction:instrucción;result:resultado;tool:herramienta;requirement:requisito',
['When you reset your password, a link is sent to your email address. Open it only if you requested the reset. The link expires after a short period. If it has expired, request a new one rather than sharing your old password with anyone.','¿Cuándo debes abrir el enlace?','Cuando solicitaste el cambio','Siempre que alguien lo envíe','Cuando un desconocido lo pida'],`
Present passive|Be más participio enfoca el proceso o resultado. Mantén la concordancia: a link is sent; links are sent.|A confirmation email is sent automatically.|Se envía un correo de confirmación automáticamente.|is sent|is send|sent is
Past passive|Was o were más participio describe un resultado pasado. No confundas el participio con la forma base.|The files were checked yesterday.|Los archivos fueron revisados ayer.|were checked|was checked|were check
Purpose|To más verbo base expresa una finalidad. Evita for más verbo base al explicar para qué haces una acción.|We use this tool to check the results.|Usamos esta herramienta para comprobar los resultados.|to check|for check|to checking
Check understanding|Una pregunta concreta comprueba comprensión mejor que solo Is that clear. Ordena el auxiliar antes del sujeto.|Could you explain what happens next?|¿Podrías explicar qué ocurre después?|what happens next|what does happen next is|what next happens does`),
unit('Conversaciones laborales','Comunicar avances, bloqueos y solicitudes.','progress:avance;blocker:impedimento;estimate:estimación;handover:traspaso;priority:prioridad',
['The team has completed the first version, but the payment test is failing. Jo has been investigating since morning. She can continue once the test account is available. During the meeting she asks who can provide it and explains which work is currently blocked.','¿Qué necesita Jo para continuar?','Una cuenta de prueba','Una nueva oficina','Cambiar de profesión'],`
Status update|Have más participio comunica trabajo terminado conectado al presente. Diferencia ese resultado de la investigación todavía en curso.|We have completed the first version.|Hemos completado la primera versión.|have completed|have complete|has completed
Duration of a task|Have been más -ing pone el foco en la duración de una actividad. Since introduce el inicio, no una cantidad.|I have been checking the logs since morning.|Llevo revisando los registros desde la mañana.|have been checking|have checking|has been checked
Polite clarification|Would you mind más -ing suaviza una petición. No uses to después de mind en esta construcción.|Would you mind explaining that again?|¿Te importaría explicar eso otra vez?|explaining|to explain|explain
Action ownership|Could you más verbo base permite asignar una acción de manera cortés. Añade resultado esperado y plazo.|Could you send the test account by noon?|¿Podrías enviar la cuenta de prueba antes del mediodía?|send|sent|to send`),
unit('Relaciones y emociones','Expresar sentimientos sin atribuir intenciones.','feeling:sentimiento;trust:confianza;support:apoyo;boundary:límite;misunderstanding:malentendido',
['Sam seemed quiet at dinner. Instead of assuming that he was angry, his friend asked whether everything was all right. Sam explained that he was worried about an exam. They agreed to talk again after he had rested.','¿Qué evitó hacer su amigo?','Suponer que estaba enfadado','Preguntarle cómo estaba','Escuchar su explicación'],`
Describe a feeling|Feel más adjetivo describe un estado. No necesitas traducir tengo nervios con have nerves en toda situación.|I feel nervous before interviews.|Me siento nervioso antes de las entrevistas.|feel nervous|feel nervously|am feel nervous
Seem and appear|Seem más adjetivo presenta una impresión. Evita convertir una impresión sobre otra persona en una certeza sobre sus intenciones.|He seems worried about the exam.|Parece preocupado por el examen.|seems worried|seems worry|seem worried
Reported statements|Al contar después lo dicho, adapta pronombres y referencias temporales. Said no lleva un destinatario directo sin to.|She said that she needed some time.|Ella dijo que necesitaba algo de tiempo.|said|told me to that|say
Reported questions|Una pregunta indirecta usa orden de afirmación. Usa if o whether para una pregunta cuya respuesta sería sí o no.|He asked if I was feeling better.|Preguntó si me encontraba mejor.|I was|was I|am I was`),
unit('Viajar y resolver','Gestionar incidencias y reclamar con respeto.','refund:reembolso;booking:reserva;replacement:sustitución;complaint:reclamación;delay:retraso',
['Our room was not ready when we arrived, although the booking confirmed an early check-in. We explained the problem and showed the confirmation. The receptionist offered to store our bags and provide another room after lunch. We accepted, but asked for written confirmation.','¿Qué pidieron tras aceptar la solución?','Confirmación por escrito','Cancelar todos los vuelos','Comprar otra maleta'],`
Describe an issue|El pasado simple explica el hecho concreto que motivó una reclamación. Sé específico antes de pedir una solución.|The room wasn't ready when we arrived.|La habitación no estaba lista cuando llegamos.|wasn't ready|didn't ready|weren't ready
Request a refund|Would like más sustantivo o to más verbo expresa una petición cortés. No uses would like con -ing aquí.|I would like to request a refund.|Quisiera solicitar un reembolso.|to request|requesting|request to
Suggest a remedy|How about más -ing propone una alternativa. Distingue una propuesta de una exigencia y escucha la respuesta.|How about changing the booking?|¿Qué tal cambiar la reserva?|changing|to change|change
Confirm a solution|Before más sujeto y verbo introduce una condición temporal. No uses will en esa subordinada futura habitual.|Please confirm the details before we leave.|Confirme los detalles antes de que nos vayamos.|leave|will leave|left will`),
unit('Aprender y trabajar mejor','Describir estrategias y hábitos.','habit:hábito;effort:esfuerzo;feedback:comentarios de mejora;practice:práctica;goal:objetivo',
['I used to study long lists without using the words. Now I practise a few phrases and return to them several days later. If I cannot remember a phrase, I use a hint and try again. I measure progress by what I can do, not by how fast I finish.','¿Cómo mide su progreso?','Por lo que puede hacer','Solo por la velocidad','Por la longitud de las listas'],`
Gerunds as subjects|Un verbo con -ing puede nombrar una actividad como sujeto. Usa un verbo singular cuando esa actividad se trata como una idea.|Practising every day helps me remember.|Practicar cada día me ayuda a recordar.|Practising|Practise to|Practised to
Verb patterns|Enjoy, avoid y keep suelen ir seguidos de -ing. Aprende la pareja completa para no decidir palabra por palabra.|I enjoy learning with other people.|Disfruto aprendiendo con otras personas.|learning|to learn|learn
Infinitive choices|Decide, hope y plan suelen ir seguidos de to más verbo. No todos los verbos comparten la misma construcción.|We decided to practise after dinner.|Decidimos practicar después de cenar.|to practise|practising|practise to
Progress comparison|Cada comparativo describe un cambio respecto a un punto de referencia. Evita combinar more con easier.|This task is easier than the previous one.|Esta tarea es más fácil que la anterior.|easier than|more easier than|easier that`),
unit('Explicar una solución','Presentar un problema, opciones y acuerdo.','cause:causa;option:opción;outcome:resultado;agreement:acuerdo;summary:resumen',
['A library website was difficult to use on phones. Volunteers collected examples before proposing a redesign. They tested larger buttons with several readers and found fewer mistakes. The final recommendation was to make one clear action visible on each screen, while keeping help easy to find.','¿Qué hicieron antes de proponer el cambio?','Recoger ejemplos del problema','Publicar una versión sin probar','Eliminar la ayuda'],`
Explain a cause|Because of va seguido de un nombre o grupo nominal; because introduce una oración con sujeto y verbo.|The service stopped because of a power cut.|El servicio se detuvo por un corte de energía.|because of|because|although
Describe an effect|As a result introduce una consecuencia de lo que acabas de explicar. No lo uses para presentar una causa anterior.|The test failed. As a result, we delayed the release.|La prueba falló. Como resultado, aplazamos la publicación.|As a result|In spite of|Such as
Offer a reasoned choice|Would más verbo base expresa una elección hipotética. Explica su motivo en lugar de presentar la opción como obligatoria.|I would choose the simpler option.|Yo elegiría la opción más sencilla.|would choose|would chose|would choosing
Summarise next steps|After más sujeto y verbo organiza el siguiente paso. En una referencia futura habitual no necesitas will en ambas partes.|We will review the results after everyone finishes.|Revisaremos los resultados cuando todos terminen.|finishes|will finishes|finish will`)
];
syllabi.B2=[
unit('Argumentar con claridad','Sostener una posición y reconocer límites.','claim:afirmación;counterargument:contraargumento;trade-off:compensación;assumption:supuesto;scope:alcance',
['A shorter working week may improve focus, but its effects depend on staffing and workload. One trial reported higher satisfaction without measuring long-term costs. Before adopting the policy, the company should compare teams with similar responsibilities and publish the limits of its evidence.','¿Qué limita la conclusión del ensayo?','No midió costes a largo plazo','No se realizó ningún ensayo','Demostró efectos idénticos en todas las empresas'],`
Balanced concession|Despite más nombre o -ing reconoce un obstáculo. Although necesita una oración; no uses despite of.|Despite the cost, the proposal is worth considering.|A pesar del coste, vale la pena considerar la propuesta.|Despite|Despite of|Although of
Qualified claims|May más verbo base ajusta una afirmación a evidencia limitada. Distingue una posibilidad de una demostración.|The policy may improve staff retention.|La política puede mejorar la retención de personal.|may improve|may improves|may to improve
Counterarguments|Nevertheless conecta una objeción con una conclusión que sigue siendo defendible. No significa que por eso.|The evidence is limited. Nevertheless, a small trial is reasonable.|La evidencia es limitada. Aun así, un ensayo pequeño es razonable.|Nevertheless|For example|In other words
Evidence and scope|Suggests that expresa una interpretación prudente. No sustituyas suggests por proves sin evidencia suficiente.|The study suggests that context matters.|El estudio sugiere que el contexto importa.|suggests that|suggest that|suggests to that`),
unit('Consecuencias hipotéticas','Examinar decisiones y resultados alternativos.','regret:arrepentimiento;alternative:alternativa;impact:impacto;prevention:prevención;possibility:posibilidad',
['The release failed because a dependency changed unexpectedly. If the team had tested the upgrade in isolation, they might have noticed the incompatibility. They cannot change yesterday, but they can add checks now. Their review focuses on conditions and safeguards rather than blaming one person.','¿En qué se centra la revisión?','En condiciones y medidas de protección','En culpar a una sola persona','En negar que hubo un fallo'],`
Third conditional|If had más participio y would have más participio imagina un pasado diferente. No uses would en ambas partes.|If we had tested it, we would have noticed the error.|Si lo hubiéramos probado, habríamos detectado el error.|would have noticed|would noticed|will have notice
Mixed conditional|Una condición pasada puede tener consecuencia presente. Identifica el tiempo de cada parte antes de elegir su forma.|If I had accepted the offer, I would live abroad now.|Si hubiera aceptado la oferta, viviría en el extranjero ahora.|would live|would have living|will lived
Wish about now|Wish más pasado expresa un deseo contrario al presente. Esa forma pasada no cuenta una experiencia terminada.|I wish I knew the answer.|Ojalá supiera la respuesta.|knew|know|will know
Regret about the past|Wish más had y participio expresa un arrepentimiento pasado. No puedes convertir ese deseo en una acción realmente realizada.|I wish we had checked the backup.|Ojalá hubiéramos comprobado la copia de seguridad.|had checked|have check|would checked`),
unit('Informar con precisión','Transmitir declaraciones, preguntas y solicitudes.','statement:declaración;source:fuente;request:solicitud;confirmation:confirmación;reference:referencia',
['The supplier said that delivery would arrive on Thursday. On Wednesday, a second message warned of a possible delay but did not give a new date. The coordinator asked whether the shipment had left and requested written confirmation rather than treating an estimate as a guarantee.','¿Qué información seguía sin confirmarse?','La nueva fecha de entrega','La existencia del proveedor','El nombre del coordinador'],`
Reported future|En un relato posterior, will puede pasar a would. Adapta también persona y referencias temporales.|She said the package would arrive on Thursday.|Dijo que el paquete llegaría el jueves.|would arrive|will arrived|would to arrive
Reporting questions|Una pregunta reportada mantiene orden de afirmación. No conserves la inversión de la pregunta directa.|They asked whether the shipment had left.|Preguntaron si el envío había salido.|had left|had it left|has leave
Reporting requests|Asked más persona más to y verbo transmite una solicitud. Distingue asked me to de asked me if.|He asked me to confirm the address.|Me pidió que confirmara la dirección.|to confirm|confirming|confirm
Reporting verbs|Recommend puede ir con -ing; no uses recommend me to como plantilla universal. Aprende cada verbo con su construcción.|They recommended checking the details first.|Recomendaron comprobar primero los detalles.|checking|to checking|check to`),
unit('Procesos y responsabilidad','Explicar resultados y quién interviene.','procedure:procedimiento;responsibility:responsabilidad;approval:aprobación;inspection:inspección;requirement:requisito',
['The documents have been reviewed, but the contract has not been approved. A legal adviser is checking one clause. The manager wants the wording changed before signing. Although most work is complete, the team must not describe the agreement as final.','¿Por qué no es definitivo el acuerdo?','Falta aprobar el contrato','No existen documentos','Ya se firmó sin condiciones'],`
Perfect passive|Have been más participio expresa un resultado pasivo conectado al presente. Conserva ambos auxiliares.|The documents have been reviewed.|Los documentos han sido revisados.|have been reviewed|have reviewed been|have been review
Passive modals|Modal más be y participio expresa una obligación o posibilidad pasiva. No elimines be.|The data must be protected.|Los datos deben protegerse.|must be protected|must protected|must be protect
Have something done|Have más objeto más participio indica que encargas una acción. No afirma necesariamente que la ejecutaste personalmente.|We had the equipment repaired.|Mandamos reparar el equipo.|had the equipment repaired|had repaired the equipment ourselves by someone|had the equipment repair
Agent and responsibility|By introduce quién realiza una acción pasiva cuando importa identificarlo. No confundas al agente con la herramienta.|The decision was approved by the board.|La decisión fue aprobada por la junta.|by|with of|from of`),
unit('Entrevistas profesionales','Explicar decisiones y aprendizaje con ejemplos.','strength:fortaleza;achievement:logro;constraint:restricción;feedback:retroalimentación;ownership:responsabilidad asumida',
['During an interview, Ada describes a project that ran over budget. She explains the constraints, her decision to reduce scope, and the result. She also identifies what she would change. Rather than claiming sole credit, she distinguishes her contribution from the work of the team.','¿Cómo presenta su contribución?','La distingue del trabajo del equipo','Se atribuye todo el mérito','Evita explicar el resultado'],`
Structured examples|What I did was más verbo base puede enfocar una acción. Sigue con el resultado para no ofrecer solo una lista de tareas.|What I did was simplify the workflow.|Lo que hice fue simplificar el flujo de trabajo.|simplify|simplified to|simplifies
Non-defining detail|Una relativa explicativa añade información con comas. No uses that para reemplazar who en esta construcción.|My manager, who joined recently, supported the change.|Mi gerente, que se incorporó hace poco, apoyó el cambio.|who|that|what
Learning from outcomes|Should have más participio permite revisar una decisión pasada. No significa que la acción se haya realizado.|We should have clarified the scope earlier.|Deberíamos haber aclarado el alcance antes.|should have clarified|should had clarified|should have clarify
Avoid overclaiming|Was able to puede describir un logro específico pasado. Explica qué hiciste realmente, sin convertir una capacidad en un resultado inventado.|I was able to restore the service within an hour.|Pude restablecer el servicio en una hora.|was able to|could to|was can to`),
unit('Reuniones que avanzan','Intervenir, aclarar y acordar acciones.','agenda:orden del día;clarification:aclaración;consensus:consenso;follow-up:seguimiento;action:acción',
['The meeting has two competing priorities: a faster launch and a more reliable checkout. Priya asks what minimum evidence is needed to release safely. The group agrees on three tests and names an owner for each. A follow-up is scheduled only after those results are available.','¿Qué transforma la discusión en un plan?','Tres pruebas con responsables','Una nueva reunión sin tareas','Elegir la opción más rápida sin datos'],`
Enter a discussion|Could I más verbo base permite pedir turno. Formula después una aportación concreta.|Could I add a point before we move on?|¿Podría añadir un punto antes de continuar?|add|to add|adding
Check an interpretation|If I understand correctly introduce una comprobación, no una acusación. Después reformula lo que crees haber entendido.|If I understand correctly, we need more evidence.|Si entiendo bien, necesitamos más evidencia.|correctly|correct|correction
Polite disagreement|Would rather más verbo base expresa preferencia. No añadas to después de rather.|I would rather test the checkout first.|Preferiría probar primero el pago.|test|to test|testing
Agree a condition|Provided that introduce una condición necesaria. En una condición futura habitual usa presente, no will.|We can launch provided that the tests pass.|Podemos publicar siempre que las pruebas pasen.|pass|will passes|passed will`),
unit('Explicar tecnología','Hacer comprensibles sistemas y decisiones.','reliability:fiabilidad;latency:latencia;dependency:dependencia;failure:fallo;recovery:recuperación',
['A cache can reduce response time, but it may serve outdated information. For a public catalogue, a short delay may be acceptable. For a payment balance, freshness is more important. The team therefore chooses a different strategy for each use case rather than treating caching as a universal solution.','¿Por qué eligen estrategias diferentes?','Las necesidades de actualización son distintas','Toda caché pierde los datos','Los pagos no usan información'],`
Explain a trade-off|While puede contrastar ventajas y límites. Haz explícito qué se gana y qué se pierde.|While caching improves speed, it can reduce freshness.|Aunque la caché mejora la velocidad, puede reducir la actualidad de los datos.|While|Because of|Despite of
Define a term|A system that más verbo identifica una propiedad. Evita repetir el sujeto después de that.|A system that retries requests needs duplicate protection.|Un sistema que reintenta peticiones necesita protección contra duplicados.|retries|it retries|retrying
State a requirement|Needs to más verbo base expresa una necesidad del sistema. No omitas to ni dupliques la tercera persona.|The service needs to validate each request.|El servicio necesita validar cada petición.|needs to validate|need to validates|needs validate
Describe uncertainty|Might have más participio propone una explicación posible sobre el pasado. No la presentes como causa confirmada.|The service might have lost the connection.|El servicio podría haber perdido la conexión.|might have lost|might has lost|might lost have`),
unit('Presentaciones','Guiar a la audiencia por una explicación.','overview:visión general;finding:hallazgo;limitation:limitación;recommendation:recomendación;audience:público',
['The presenter starts with the problem users face, then explains how the team tested two solutions. The first was faster but caused more mistakes. She recommends the second, notes the small sample size, and invites questions about the assumptions before discussing next steps.','¿Qué limitación reconoce?','El tamaño pequeño de la muestra','La ausencia total de pruebas','Que nadie cometió errores'],`
Signpost a talk|Start by más -ing presenta el primer paso. Las señales ayudan a seguir el contenido sin memorizar cada palabra.|I'll start by outlining the problem.|Empezaré describiendo el problema.|outlining|to outline|outline
Refer to a visual|As you can see orienta hacia la evidencia visible. Explica qué importa, no solo que existe una gráfica.|As you can see, errors fell after the change.|Como pueden ver, los errores disminuyeron tras el cambio.|can see|can to see|can seeing
Emphasise a finding|What matters is enfoca la idea central. No conviertas un hallazgo limitado en una promesa universal.|What matters is whether people can complete the task.|Lo que importa es si las personas pueden completar la tarea.|whether|that whether if|which whether
Invite questions|Antes de una pregunta indirecta, conserva el orden sujeto-verbo. Comprueba el punto concreto que necesita la audiencia.|Could you explain which result concerns you?|¿Podría explicar qué resultado le preocupa?|which result concerns you|which does result concern you|which result does concerns`),
unit('Noticias y sociedad','Distinguir información, opinión e inferencia.','headline:titular;source:fuente;bias:sesgo;coverage:cobertura;verification:verificación',
['An article claims that a new app improves learning. It quotes enthusiastic users but provides no comparison group. A separate report describes mixed results across age groups. A careful reader can welcome the idea while asking for stronger evidence and checking who funded each report.','¿Qué falta en el primer artículo?','Un grupo de comparación','Opiniones entusiastas','La mención de una aplicación'],`
Deduce cautiously|Must have más participio expresa una deducción fuerte sobre el pasado, no una obligación pasada. Asegura que existen indicios.|They must have checked the source before publishing.|Deben de haber comprobado la fuente antes de publicar.|must have checked|must had checked|must have check
Negative deduction|Can't have más participio expresa una deducción negativa. No significa simplemente que una acción estaba prohibida.|The figures can't have come from that survey.|Esas cifras no pueden proceder de esa encuesta.|can't have come|can't has come|can't have came
Reference clearly|This puede retomar una idea completa. Añade un sustantivo cuando el referente podría confundirse.|This limitation affects the conclusion.|Esta limitación afecta a la conclusión.|affects|affecting|affect to
Distinguish a claim|According to identifica la fuente de una afirmación. Citarla no convierte automáticamente el contenido en verdadero.|According to the report, the results varied.|Según el informe, los resultados variaron.|According to|According with|According of`),
unit('Negociar y cerrar','Resolver diferencias y resumir compromisos.','proposal:propuesta;concession:concesión;commitment:compromiso;deadline:fecha límite;fallback:alternativa de respaldo',
['The client wants delivery on Monday, but the team needs more testing time. They offer a smaller release on Monday and the remaining features on Thursday. The client accepts on condition that payments work reliably. The agreement records the scope and who will approve the final test.','¿Qué condición pone el cliente?','Que los pagos sean fiables','Que no se pruebe nada','Que se entregue todo el domingo'],`
Conditional offer|Would be willing to expresa disposición condicionada. Usa una condición concreta para que la oferta no resulte ambigua.|We would be willing to reduce the scope.|Estaríamos dispuestos a reducir el alcance.|to reduce|reducing|reduce to
Explore an option|What if más pasado puede explorar una alternativa hipotética. Distingue explorar de aceptar un compromiso.|What if we delivered the smaller version first?|¿Y si entregáramos primero la versión reducida?|delivered|would delivered|deliver would
Set a boundary|Unless expresa una condición negativa necesaria. Deja claro qué falta antes de poder comprometerte.|We cannot commit unless the scope is agreed.|No podemos comprometernos si no se acuerda el alcance.|is agreed|will agrees|agreed is be
Summarise commitments|By más momento marca un plazo límite; until indica continuidad hasta ese momento. Elegir uno cambia el compromiso.|We will send the revised proposal by Friday.|Enviaremos la propuesta revisada como máximo el viernes.|by|until|during of`)
];
syllabi.C1=[
unit('Precisar sin exagerar','Ajustar certeza, evidencia y alcance.','plausibility:plausibilidad;qualification:matización;likelihood:probabilidad;inference:inferencia;certainty:certeza',
['The preliminary findings are consistent with an improvement, though they do not establish causation. Participants selected their own groups, and their previous experience was not controlled. It would therefore be premature to attribute the entire difference to the intervention. A follow-up should investigate alternative explanations rather than merely repeat the preferred claim.','¿Por qué sería prematuro afirmar causalidad?','Hay explicaciones alternativas sin controlar','Los grupos fueron asignados al azar','No se observó diferencia alguna'],`
Hedging evidence|Appears to ajusta la certeza sin ocultar el resultado. No equivale a una demostración causal.|The intervention appears to improve retention.|La intervención parece mejorar la retención.|appears to improve|appears improving to|appear to improves
Degrees of likelihood|Is likely to expresa probabilidad. Conserva to y distingue probable de seguro.|The effect is likely to vary across groups.|Es probable que el efecto varíe entre grupos.|is likely to|is likely for|likely is that to
Tentative interpretation|Would seem to introduce una interpretación prudente. La cautela debe corresponder a un límite real de la evidencia.|This would seem to support a narrower claim.|Esto parecería respaldar una afirmación más limitada.|would seem to|would seems to|would seem for
Scope of a conclusion|Not necessarily niega una inferencia obligatoria, no el hecho inicial. Explica qué no se deduce.|A higher score does not necessarily imply deeper understanding.|Una puntuación mayor no implica necesariamente una comprensión más profunda.|necessarily|necessary|necessity`),
unit('Énfasis con intención','Destacar información sin alterar el significado.','emphasis:énfasis;restriction:restricción;contrast:contraste;focus:foco;priority:prioridad',
['Only after users had tried the prototype did the team recognise the navigation problem. The issue was not the amount of content but the lack of a clear next step. What mattered most was making the sequence visible. The team then reduced competing actions rather than removing the learning material.','¿Cuál era el problema principal?','No se distinguía el siguiente paso','Había poco contenido','Nadie pudo abrir el prototipo'],`
Negative inversion|Con rarely inicial invierte auxiliar y sujeto. Si no hay auxiliar, añade do o does según el sujeto.|Rarely do we see such a clear improvement.|Rara vez vemos una mejora tan clara.|do we see|we see|we do see
Only after|Only after inicial provoca inversión en la oración principal, no dentro de la subordinada temporal.|Only after the test did we recognise the problem.|Solo después de la prueba reconocimos el problema.|did we recognise|we recognised|did we recognised
Cleft focus|It was X that destaca un elemento. Comprueba qué información presentas como contraste.|It was the sequence that confused the users.|Fue la secuencia lo que confundió a los usuarios.|that|what|which it
What matters|Una estructura con what puede enfocar una necesidad o resultado. No la confundas con una pregunta directa.|What we need is a clearer explanation.|Lo que necesitamos es una explicación más clara.|What we need|What do we need|That we need what`),
unit('Registro y cortesía','Adaptar el mensaje a relación y situación.','register:registro;tact:tacto;stance:postura;wording:redacción;courtesy:cortesía',
['An engineer notices that a colleague has omitted an important check. In a private message, she asks whether they could review the assumptions together. In the incident report, she records the omission directly and without personal criticism. The facts remain the same, while the wording changes to suit the purpose and audience.','¿Qué cambia entre los dos mensajes?','La redacción según su propósito','Los hechos del incidente','La existencia de la comprobación'],`
Tactful requests|I was wondering whether distancia una petición y suaviza su tono. La pregunta incluida mantiene orden de afirmación.|I was wondering whether we could review the assumptions.|Me preguntaba si podríamos revisar los supuestos.|we could review|could we review|we could to review
Formal requests|Would be grateful if formula una solicitud formal. Usa cortesía proporcional, sin esconder lo que necesitas.|I would be grateful if you could confirm receipt.|Le agradecería que confirmara la recepción.|could confirm|could to confirm|could confirmed
Diplomatic correction|May have más participio permite señalar una posible omisión sin atribuir intención. Después verifica los hechos.|We may have overlooked one requirement.|Puede que hayamos pasado por alto un requisito.|may have overlooked|may has overlooked|may have overlook
Register shifts|Regarding introduce el tema en un registro formal. Evita regarding to; una forma más sencilla también puede ser adecuada.|Regarding your request, we need one clarification.|Sobre su solicitud, necesitamos una aclaración.|Regarding|Regarding to|Regarding for`),
unit('Cohesión y síntesis','Conectar argumentos sin ocultar su relación.','cohesion:cohesión;premise:premisa;implication:implicación;distinction:distinción;synthesis:síntesis',
['One report measures speed, whereas another examines error rates. Their conclusions appear inconsistent only if performance is treated as a single quantity. Taken together, they suggest that the design improves speed at the expense of accuracy. A useful summary must preserve that distinction instead of declaring one report wrong.','¿Qué debe conservar el resumen?','La diferencia entre velocidad y precisión','Solo la conclusión más favorable','Una acusación contra uno de los informes'],`
Concession and contrast|Whereas contrasta hechos; nonetheless mantiene una conclusión pese a una objeción. Decide primero la relación lógica.|The design is faster, whereas the old version is more accurate.|El diseño es más rápido, mientras que la versión anterior es más precisa.|whereas|because of|despite of
Referencing ideas|The former y the latter remiten respectivamente al primero y al segundo de dos elementos. Evita usarlos con referentes confusos.|Of speed and accuracy, the latter matters more here.|Entre velocidad y precisión, la segunda importa más aquí.|latter|later|latest
Participle clauses|Taken together condensa una condición interpretativa: al considerar ambos elementos. Asegura que el referente sea inequívoco.|Taken together, the reports reveal a trade-off.|Considerados conjuntamente, los informes revelan una compensación.|Taken together|Took together|Taking by together
Synthesis with limits|Insofar as delimita hasta qué punto se sostiene algo. No lo uses como sustituto decorativo de because.|The conclusion is useful insofar as the samples are comparable.|La conclusión es útil en la medida en que las muestras sean comparables.|insofar as|in spite as|in so far of`),
unit('Negociación compleja','Precisar condiciones y gestionar desacuerdos.','leverage:capacidad negociadora;concession:concesión;contingency:contingencia;feasibility:viabilidad;undertaking:compromiso',
['The supplier offers a discount in exchange for a longer contract. The buyer accepts in principle but asks for a review clause if service quality declines. Neither party can guarantee future demand. They agree on measurable service targets and a procedure for revisiting the terms, keeping the concession conditional rather than absolute.','¿Qué mantiene condicionada la aceptación?','Una cláusula de revisión de calidad','Una promesa de demanda garantizada','La eliminación de objetivos medibles'],`
Conditional acceptance|Subject to más nombre establece una condición. No significa sobre el tema de en este uso contractual.|We agree in principle, subject to final approval.|Estamos de acuerdo en principio, sujeto a aprobación final.|subject to|subject of|subject for
Hypothetical concession|Were you to más verbo base plantea una condición hipotética formal sin if. La consecuencia suele llevar would.|Were you to extend the contract, we would reconsider the fee.|Si ampliaran el contrato, reconsideraríamos la tarifa.|Were you to|Were to you|Would you to
Provisional agreement|Provided that introduce una condición explícita. Distingue un acuerdo provisional de uno sin reservas.|We can proceed provided that the targets remain measurable.|Podemos continuar siempre que los objetivos sigan siendo medibles.|provided that|provided of|provided to that
Clarify a commitment|Commit to suele ir seguido de nombre o -ing. El to aquí es preposición, no parte de un infinitivo.|We cannot commit to delivering the full scope yet.|Todavía no podemos comprometernos a entregar todo el alcance.|delivering|deliver|delivered to`),
unit('Debate y objeciones','Responder al argumento más fuerte de la otra parte.','rebuttal:refutación;objection:objeción;premise:premisa;validity:validez;consistency:coherencia',
['A speaker argues that remote work always reduces collaboration. Her opponent accepts that some teams struggle but questions the word always. She distinguishes poor coordination from physical distance and proposes comparing teams with similar tasks. This addresses the claim without denying the experiences that motivated it.','¿Qué parte de la afirmación cuestiona?','La generalización siempre','Que algunos equipos tengan dificultades','La existencia del trabajo remoto'],`
Challenge a premise|Whether introduce una cuestión abierta. Cuestionar una premisa no equivale a negar toda la experiencia del interlocutor.|The question is whether distance is the main cause.|La cuestión es si la distancia es la causa principal.|whether|that whether if|which whether
Concede precisely|Granted that reconoce algo sin aceptar la conclusión entera. Después explica qué inferencia cuestionas.|Granted that some teams struggle, the cause remains unclear.|Admitiendo que algunos equipos tienen dificultades, la causa sigue sin estar clara.|Granted that|Granted of|Granted to
Reframe a distinction|Not so much X as Y desplaza el foco entre dos interpretaciones. Mantén estructuras paralelas.|It is not so much a location problem as a coordination problem.|No es tanto un problema de ubicación como de coordinación.|as|than of|that of
Test an implication|Were that true introduce una hipótesis para examinar su consecuencia. No presenta la hipótesis como un hecho comprobado.|Were that true, every remote team would fail.|Si eso fuera cierto, todos los equipos remotos fracasarían.|Were that true|Was that truly be|Would that true`),
unit('Lenguaje natural','Usar combinaciones y expresiones en contexto.','collocation:colocación;idiom:expresión idiomática;nuance:matiz;implication:implicación;context:contexto',
['When the manager says that the proposal needs work, she does not necessarily mean it should be abandoned. A colleague asks which assumptions need revisiting. That question turns a vague reaction into an actionable discussion. Natural phrasing helps, but shared understanding still depends on context and clarification.','¿Qué convierte la reacción en una acción concreta?','Preguntar qué supuestos deben revisarse','Interpretarla como cancelación inmediata','Repetir una expresión sin contexto'],`
Verb noun combinations|Make a decision es una combinación habitual. Apréndela en una situación, sin traducir hacer automáticamente como do.|We need to make a decision today.|Necesitamos tomar una decisión hoy.|make|do|put
Phrasal verbs|Bring up introduce un tema. El significado del conjunto puede diferir del de cada palabra.|She brought up a concern during the meeting.|Ella planteó una preocupación durante la reunión.|brought up|brought under|brought of
Idioms with context|On the same page expresa entendimiento compartido, no una página física en este contexto.|Let's check that we are on the same page.|Comprobemos que nos entendemos.|on the same page|in the same leaf|at same paper
Clarify figurative meaning|By that, do you mean pide precisión sobre una expresión. La fluidez también incluye reparar malentendidos.|By that, do you mean we should revise the plan?|Con eso, ¿quieres decir que deberíamos revisar el plan?|do you mean|you do mean is|are you mean`),
unit('Comunicación intercultural','Explicar perspectivas y evitar suposiciones.','perspective:perspectiva;convention:convención;interpretation:interpretación;assumption:supuesto;mediation:mediación',
['A brief reply is interpreted as rude by one colleague and efficient by another. Rather than assigning motives based on nationality, the team asks about individual preferences. They agree to state urgent requests explicitly and check meaning when tone is ambiguous. Cultural awareness guides curiosity; it does not replace asking the person.','¿Qué evita hacer el equipo?','Atribuir motivos por nacionalidad','Preguntar preferencias personales','Aclarar las peticiones urgentes'],`
Avoid generalisations|Tend to expresa una tendencia, no una regla universal. No atribuyas una preferencia a toda una población.|People tend to interpret silence differently.|Las personas tienden a interpretar el silencio de formas distintas.|tend to|tends for|tend for to
Explain a viewpoint|From their perspective sitúa una interpretación sin afirmar que sea la única válida. Después puedes contrastarla con otra.|From their perspective, the reply seemed abrupt.|Desde su perspectiva, la respuesta pareció brusca.|perspective|prospective|perspectively
Mediate a misunderstanding|What she meant was puede reformular una intención confirmada. No inventes el pensamiento ajeno si todavía no lo has comprobado.|What she meant was that the deadline was flexible.|Lo que quiso decir fue que el plazo era flexible.|What she meant|What did she meant|That what she mean
Check without accusing|Would you say introduce una pregunta exploratoria. Mantén el orden declarativo dentro de la proposición que sigue.|Would you say the wording felt too direct?|¿Dirías que la redacción resultó demasiado directa?|felt|did felt|feeling was did`),
unit('Explicar sistemas complejos','Conectar mecanismos, límites e incidentes.','resilience:resiliencia;bottleneck:cuello de botella;consistency:consistencia;observability:observabilidad;assurance:garantía',
['The service remained available during a regional failure because traffic was redirected. However, some records were briefly outdated. The incident therefore demonstrates availability under those conditions, not perfect consistency or immunity to every failure. The review separates observed behaviour from guarantees that were never tested.','¿Qué no demuestra el incidente?','Inmunidad frente a cualquier fallo','Que hubo redirección de tráfico','Que algunos datos estuvieron desactualizados'],`
Mechanism and consequence|Thereby más -ing enlaza una acción con su efecto. Debe existir una relación causal que puedas explicar.|Traffic was redirected, thereby reducing downtime.|Se redirigió el tráfico, reduciendo así la interrupción.|reducing|reduce|reduced to
Distinguish guarantees|Does not entail expresa que una conclusión no se deduce necesariamente. Evita prometer propiedades no comprobadas.|Availability does not entail perfect consistency.|La disponibilidad no implica consistencia perfecta.|entail|entails|entailing
Counterfactual incident|Had más sujeto y participio introduce una condición pasada formal sin if. La consecuencia mantiene would have.|Had the backup failed, recovery would have taken longer.|Si la copia hubiera fallado, la recuperación habría tardado más.|Had the backup failed|Has the backup failed|Would the backup failed
Explain a limitation|To the extent that delimita el alcance de una explicación. Relaciona el límite con condiciones observables.|The test is useful to the extent that it reflects real traffic.|La prueba es útil en la medida en que refleja tráfico real.|to the extent that|at the extent of|to extent whether`),
unit('Comunicar con autonomía','Sintetizar, presentar y responder preguntas exigentes.','synthesis:síntesis;implication:implicación;priority:prioridad;qualification:matización;recommendation:recomendación',
['The final presentation combines user interviews, performance tests and operational constraints. Each source answers a different question. The recommendation favours a gradual rollout, with explicit criteria for stopping or continuing. When challenged, the presenter distinguishes what the evidence supports from what remains a judgement under uncertainty.','¿Cómo propone desplegar el cambio?','Gradualmente con criterios explícitos','De una vez sin condiciones','Sin atender restricciones operativas'],`
Summarise distinct sources|Taken as a whole permite una síntesis sin borrar diferencias. Explica también qué aporta cada fuente.|Taken as a whole, the evidence supports a gradual rollout.|En conjunto, la evidencia respalda un despliegue gradual.|Taken as a whole|Took as whole|Taking of whole
Answer a challenge|That depends on introduce una condición relevante. Debe seguir una explicación concreta, no una evasiva.|That depends on how the risk is measured.|Eso depende de cómo se mida el riesgo.|how the risk is measured|how is the risk measured|how the risk measured is does
Reformulate precisely|In other words reformula la misma idea. No lo uses para introducir una afirmación más fuerte que la anterior.|In other words, the recommendation is conditional.|En otras palabras, la recomendación está condicionada.|In other words|On other words|At another words
Close with boundaries|On balance pondera razones contrapuestas. Expresa una conclusión razonada con sus condiciones, no certeza absoluta.|On balance, I would recommend the smaller trial.|Sopesándolo todo, recomendaría el ensayo más pequeño.|On balance|In balanced|At balancing`)
];
syllabi.C2=[
unit('Leer entre líneas','Distinguir lo dicho, lo implicado y lo incierto.','implicature:implicatura;reservation:reserva;understatement:atenuación;stance:postura;ambiguity:ambigüedad',
['Asked whether the proposal was practical, the director called it ambitious and immediately asked about the budget. The adjective alone could express admiration or doubt; the follow-up makes concern about feasibility more plausible. Even so, it would overstate the evidence to report that the director rejected the proposal. Interpretation should preserve both contextual clues and remaining uncertainty.','¿Qué interpretación supera la evidencia?','Afirmar que rechazó la propuesta','Que le preocupa la viabilidad','Que preguntó por el presupuesto'],`
Interpret reservations|May well expresa una posibilidad plausible. No convierte una implicatura contextual en una intención comprobada.|She may well be expressing a reservation.|Es muy posible que esté expresando una reserva.|may well be|may well to be|may wells be
Understatement|Not exactly puede suavizar una valoración negativa. Interpreta la situación y el tono antes de traducirlo literalmente.|The response was not exactly enthusiastic.|La respuesta no fue precisamente entusiasta.|not exactly|not exact|no exactly
Presuppositions|Still puede presuponer continuidad desde un estado anterior. Detectar esa presuposición ayuda a cuestionar la pregunta con tacto.|Are you still using the old process?|¿Sigues utilizando el proceso anterior?|still|yet of|already of
Avoid overinterpretation|Would be reading too much into señala una inferencia excesiva. Explica qué información adicional haría falta.|We would be reading too much into that remark.|Estaríamos interpretando demasiado ese comentario.|reading too much into|reading too many onto|read too much to`),
unit('Ironía y lenguaje figurado','Interpretar expresiones sin asumir un único tono.','irony:ironía;sarcasm:sarcasmo;metaphor:metáfora;literal:literal;cue:indicio',
['After a third outage, someone says, Brilliant timing. The words are positive, but the context suggests irony. A transcript cannot reproduce every vocal cue, so an analyst should distinguish a likely reading from certainty. In a public incident report, a neutral paraphrase would communicate frustration more reliably than reproducing the remark without explanation.','¿Por qué hace falta cautela?','La transcripción no recoge todos los indicios de voz','Las palabras siempre son literales','No hubo ninguna interrupción'],`
Contextual irony|Hardly puede invertir una valoración aparente. No supongas que toda frase positiva sea irónica sin contexto.|That was hardly the ideal moment.|Ese no era precisamente el momento ideal.|hardly|hard|hardness
Conventional metaphors|A stumbling block nombra un obstáculo figurado. Explica qué dificultad concreta representa en la situación.|Funding remains the main stumbling block.|La financiación sigue siendo el principal obstáculo.|stumbling block|stumbled road|stumble wall
Idiomatic flexibility|Miss the point significa no captar lo esencial. No equivale a olvidar un punto físico.|That response misses the point of the question.|Esa respuesta no capta lo esencial de la pregunta.|misses the point|loses the dot|misses to point
Paraphrase tone|Came across as describe la impresión causada. Distingue efecto percibido e intención confirmada.|The remark came across as dismissive.|El comentario se percibió como despectivo.|came across as|came across to|came through of`),
unit('Precisión léxica','Elegir palabras según fuerza, registro y combinación.','connotation:connotación;precision:precisión;distinction:distinción;collocation:colocación;semantic:semántico',
['Calling a result inconclusive differs from calling it irrelevant. The former concerns what can be inferred; the latter concerns whether it matters to the question. A summary that substitutes one for the other changes the argument. Precision requires choosing a word for its contextual meaning rather than because it sounds more advanced.','¿Qué cambia al sustituir inconcluso por irrelevante?','El argumento','Solo la longitud de la frase','Nada sobre su significado'],`
Fine distinctions|Inconclusive significa que no permite una conclusión firme, no que carezca de relevancia. Atiende a la inferencia concreta.|The evidence remains inconclusive.|La evidencia sigue sin ser concluyente.|inconclusive|irrelevant by definition|concluded
Verb strength|Undermine debilita una afirmación; refute pretende demostrar que es falsa. No las trates como sinónimos exactos.|These inconsistencies undermine the argument.|Estas incoherencias debilitan el argumento.|undermine|underline necessarily|underlie necessarily
Register and intensity|Considerable expresa una magnitud relevante sin afirmar totalidad. Elige la fuerza según lo que puedas sostener.|The revision requires considerable effort.|La revisión exige un esfuerzo considerable.|considerable|considerably|consideration
Collocational precision|Draw a distinction combina un verbo y un nombre de forma convencional. Memoriza la expresión en un contraste útil.|We must draw a distinction between access and ownership.|Debemos distinguir entre acceso y propiedad.|draw|do|put out`),
unit('Sintaxis flexible','Reformular estructuras complejas conservando el sentido.','ellipsis:elipsis;fronting:anteposición;inversion:inversión;reference:referencia;parallelism:paralelismo',
['The committee accepted the narrow claim, not the broader one. So did the external reviewers, though for different reasons. What neither group accepted was the assumption that one successful trial established universal effectiveness. A faithful reformulation must preserve the contrast and the limited scope of agreement.','¿Qué rechazaron ambos grupos?','La conclusión de eficacia universal','La afirmación limitada','La existencia del ensayo'],`
Ellipsis|So más auxiliar y sujeto evita repetir una afirmación positiva. El auxiliar debe corresponder al tiempo anterior.|The committee agreed, and so did the reviewers.|El comité estuvo de acuerdo y los revisores también.|so did the reviewers|so the reviewers did always|so were the reviewers do
Negative agreement|Neither más auxiliar y sujeto expresa coincidencia negativa. No añadas otra negación al auxiliar.|I didn't accept the claim, and neither did she.|No acepté la afirmación y ella tampoco.|neither did she|neither she didn't|neither does she did
Fronted emphasis|Such más be y sujeto puede enfatizar una magnitud en registro formal. Usa esta forma por intención, no por exhibición.|Such was the uncertainty that no decision was made.|Tal era la incertidumbre que no se tomó ninguna decisión.|Such was|Such were it|Such did
Parallel contrast|Not X but Y mantiene formas comparables para precisar el foco. Evita que la reformulación cambie qué se niega.|The issue is not speed but reliability.|El problema no es la velocidad sino la fiabilidad.|but|than of|rather of`),
unit('Fuentes en tensión','Reconstruir argumentos y comparar supuestos.','premise:premisa;provenance:procedencia;corroboration:corroboración;methodology:metodología;discrepancy:discrepancia',
['Two reviews reach different conclusions about the same policy. One measures short-term participation; the other considers sustained access among people with limited connectivity. Their disagreement partly reflects different definitions of success. A synthesis should identify those definitions, examine each method, and avoid manufacturing consensus by quietly dropping the less convenient outcome.','¿Qué explica parte de la discrepancia?','Diferentes definiciones de éxito','Que analizan políticas distintas','Que usan métodos idénticos y resultados idénticos'],`
Identify an assumption|Rests on nombra una base argumental. Examina si la premisa está justificada antes de aceptar la conclusión.|The conclusion rests on a narrow definition of success.|La conclusión se basa en una definición estrecha del éxito.|rests on|rests to|rests of
Source attribution|Purports to indica lo que una fuente pretende hacer, con distancia crítica. No implica automáticamente falsedad.|The report purports to measure long-term impact.|El informe pretende medir el impacto a largo plazo.|purports to|purports for|purporting to does
Apparent disagreement|In part matiza una explicación como parcial. No borres otras causas posibles de discrepancia.|The discrepancy stems in part from different methods.|La discrepancia se debe en parte a métodos distintos.|in part|on part|at partly
Synthesis without distortion|Rather than más -ing permite contrastar dos formas de actuar. Preserva también la evidencia incómoda.|We should compare assumptions rather than force a consensus.|Debemos comparar supuestos en vez de forzar un consenso.|force|forces|forced to`),
unit('Mediación accesible','Explicar ideas complejas a públicos distintos.','accessibility:accesibilidad;analogy:analogía;limitation:limitación;audience:público;reformulation:reformulación',
['A specialist explains encryption to a family by comparing it with a locked box. The analogy helps with secrecy but says little about identity or key management. She states those limits and asks the listeners to describe what the box does and does not guarantee. Accessibility comes from preserving the important distinctions, not merely shortening the vocabulary.','¿Qué hace útil y rigurosa la analogía?','Explicar también sus límites','Afirmar que cubre todos los detalles','Evitar comprobar la comprensión'],`
Reformulate a mechanism|Put simply anuncia una reformulación, no permiso para eliminar una condición esencial. Conserva lo que cambia una decisión.|Put simply, the lock protects content, not every aspect of identity.|Dicho de forma sencilla, el candado protege el contenido, no todo aspecto de la identidad.|Put simply|Put simple|Putting simplicity
Bound an analogy|Breaks down expresa dónde deja de funcionar una comparación. Explicar el límite evita una falsa equivalencia.|The analogy breaks down when we discuss shared keys.|La analogía deja de funcionar al hablar de claves compartidas.|breaks down|breaks of|breaks to
Adjust a register|In everyday terms acerca un concepto sin afirmar que su versión breve sea exhaustiva. Ofrece ampliar si hace falta.|In everyday terms, this is a way of checking who sent the message.|En términos cotidianos, es una forma de comprobar quién envió el mensaje.|In everyday terms|On everyday terms|At everyday term
Verify understanding|Would you put pide una reformulación personal. Escucha qué distinciones conserva antes de decidir si comprendió.|How would you put that in your own words?|¿Cómo lo explicarías con tus propias palabras?|would you put|you would put is|would you putting`),
unit('Persuasión responsable','Diseñar mensajes convincentes sin ocultar incertidumbre.','framing:encuadre;salience:relevancia destacada;qualification:matización;disclosure:divulgación;accountability:rendición de cuentas',
['A campaign highlights a high success rate without mentioning that most applicants were excluded from the trial. The figure may be accurate for participants yet misleading for the public. A responsible presentation states the selection criteria and the denominator, allowing readers to judge whether the result applies to them.','¿Por qué puede resultar engañosa la cifra?','Omite a quiénes se excluyó del ensayo','Toda tasa de éxito es falsa','No hubo participantes'],`
Precision of scope|Among those who delimita la población descrita. Una tasa sin denominador puede inducir una interpretación demasiado amplia.|The rate was high among those who completed the trial.|La tasa fue alta entre quienes completaron el ensayo.|among those who|between that who|among which people who does
Concede without concealment|Accurate yet misleading distingue veracidad literal y efecto comunicativo. Explica qué información falta.|The statement is accurate yet misleading.|La afirmación es exacta pero engañosa.|yet|because of|despite of
Avoid implied certainty|Should not be taken to mean bloquea una inferencia que el texto no justifica. No dejes la limitación implícita.|The result should not be taken to mean that everyone benefits.|El resultado no debe interpretarse como que todos se benefician.|be taken to mean|be took to mean|taken be mean
Accountable recommendations|It is incumbent on expresa responsabilidad formal. El registro debe corresponder al público y propósito.|It is incumbent on us to disclose the limitations.|Nos corresponde revelar las limitaciones.|incumbent on|incumbent to|incumbency of`),
unit('Conversaciones difíciles','Corregir, discrepar y reparar relaciones.','repair:reparación;face:tacto social;acknowledgement:reconocimiento;intent:intención;impact:impacto',
['A senior colleague dismisses a concern during a meeting. Later, she acknowledges the effect of her wording without claiming that good intentions erased it. She restates the concern fairly, asks what she missed, and agrees on a way to raise similar issues. Repair involves both understanding the harm and changing the interaction.','¿Qué reconoce la colega?','El efecto de sus palabras','Que su intención elimina todo daño','Que nadie planteó una preocupación'],`
Acknowledge an effect|Regardless of distingue un efecto de la intención. Reconocer impacto no exige inventar motivos ni negar hechos.|Regardless of my intention, the wording was dismissive.|Independientemente de mi intención, la redacción fue despectiva.|Regardless of|Regardless to|Irregardless from
Repair a formulation|Let me rephrase permite corregir la expresión sin fingir que la frase anterior no ocurrió. Explica el cambio relevante.|Let me rephrase that more carefully.|Permíteme reformularlo con más cuidado.|rephrase|to rephrase|rephrasing
Invite correction|Had overlooked puede reconocer un límite previo de tu comprensión. Pide una corrección concreta y escúchala.|Is there anything I had overlooked?|¿Hay algo que yo hubiera pasado por alto?|had overlooked|had overlook|have overlooking
Distinguish intent and impact|Notwithstanding más nombre introduce una concesión formal. Usa una forma sencilla si facilita la conversación.|Notwithstanding my intentions, I accept the criticism.|Pese a mis intenciones, acepto la crítica.|Notwithstanding|Notwithstanding of|Notwithstand to`),
unit('Inferencia en habla conectada','Combinar pistas lingüísticas y contexto.','stress:acento enfático;intonation:entonación;chunk:grupo de palabras;contrast:contraste;cue:indicio',
['In I thought you had sent it, changing the stressed word can change the implied contrast. Stress on you may contrast people; stress on sent may contrast actions. Written words alone cannot determine every reading. The listener should combine wording, tone and situation, and ask a focused question when the implication matters.','¿Qué limita la interpretación por escrito?','No recoge toda la información de énfasis y tono','El inglés no usa contraste','Todas las palabras tienen una única lectura'],`
Contrastive focus|It was you who enfoca a una persona frente a alternativas. Escucha qué elemento recibe énfasis antes de inferir el contraste.|It was you who confirmed the date.|Fuiste tú quien confirmó la fecha.|who|what|which it
Reduced forms|I'd puede contraer I had o I would. El verbo siguiente ayuda a distinguirlas: participio frente a forma base.|I had already sent the file before the call.|Ya había enviado el archivo antes de la llamada.|had|would|did
Connected meaning|Would've representa would have en habla. No escribas would of por semejanza sonora.|I would have called if I had known.|Habría llamado si lo hubiera sabido.|would have|would of|would has
Check the implication|Are you suggesting that permite verificar una inferencia. No presupone que tu lectura sea correcta.|Are you suggesting that we should postpone the decision?|¿Estás sugiriendo que deberíamos aplazar la decisión?|suggesting|suggest|suggested to`),
unit('Síntesis autónoma','Integrar matices y sostener una posición revisable.','judgement:juicio;qualification:matización;robustness:solidez;revision:revisión;implication:implicación',
['After examining conflicting evidence, the panel recommends a limited trial rather than immediate adoption. The recommendation is robust to small changes in cost but sensitive to assumptions about long-term demand. The chair explains what new evidence would reverse the decision. This makes the position accountable without pretending that uncertainty has disappeared.','¿Qué haría revisable la posición?','Explicar qué evidencia cambiaría la decisión','Negar que haya incertidumbre','Ignorar los costes y la demanda'],`
Robust conclusions|Holds up expresa que una conclusión resiste examen. Indica bajo qué cambios sigue siendo defendible.|The conclusion holds up under those assumptions.|La conclusión se sostiene bajo esos supuestos.|holds up|holds of|holds onto of
Sensitivity|Is contingent on explicita una dependencia. No significa que la conclusión sea incondicional.|The recommendation is contingent on future demand.|La recomendación depende de la demanda futura.|contingent on|contingent to|contingency of
Revisable judgement|Were new evidence to emerge presenta una condición formal futura. Explica qué tipo de evidencia justificaría revisar el juicio.|Were new evidence to emerge, we would reconsider.|Si surgiera nueva evidencia, lo reconsideraríamos.|Were new evidence to emerge|Would new evidence emerged|Was new evidence emerging to
Nuanced closure|All things considered pondera factores sin afirmar que se hayan resuelto todas las dudas. Cierra con alcance y siguiente paso.|All things considered, a limited trial is the sounder choice.|Considerándolo todo, un ensayo limitado es la opción más sólida.|All things considered|All things considering|All thing consideration`)
];

const colours=['#604095','#9a4d16','#a32959','#076d66','#7d5906','#514088','#55720b','#1f568d','#99442d','#344e9e'];
export const advancedUnits=[];
export const advancedLessons=[];
export const advancedExamItems=[];
for(const [level,list] of Object.entries(syllabi))list.forEach((u,ui)=>{
 const unitId=`${level.toLowerCase()}-unit-${ui+1}`,words=u.words.split(';').map(pair=>{const [word,meaning]=pair.split(':');return{word,meaning};});
 advancedUnits.push({id:unitId,level,number:ui+1,title:u.title,goal:u.goal,emoji:['🌱','📖','💬','🧭','🛠️','🤝','🌍','🎯','🔎','🚀'][ui],color:colours[ui],tint:'#f3eff8'});
 u.rows.forEach(([title,rule,example,translation,correct,a,b],li)=>{
  if(!example.includes(correct))throw new Error(`Missing cloze: ${level} ${title}`);
  const id=`${level.toLowerCase()}-u${String(ui+1).padStart(2,'0')}-l${li+1}`;
  const gap=example.replace(correct,'___'),grammar=[{prompt:`Completa en esta situación: ${gap}`,options:[correct,a,b],answer:0,why:rule}];
  // The second form requires sentence production, not another multiple-choice guess.
  const production={id:`${id}-write`,lessonId:id,unitId,type:'text',skill:'grammar',prompt:`Expresa esta idea en inglés: «${translation}»`,accepted:[example],model:example,why:rule,mode:'practice'};
  const sceneText=`${u.story[0]} ${example}`;
  const meaningQ={prompt:`¿Qué expresa la frase «${example}»?`,options:[translation,...u.rows.filter(r=>r[2]!==example).slice(0,2).map(r=>r[3])],answer:0};
  const detailQ={prompt:u.story[1],options:u.story.slice(2),answer:0};
  advancedLessons.push({id,level,unitId,unitNumber:ui+1,number:ui*4+li+1,title,goal:`${u.goal} En esta sesión: ${title}.`,duration:25,explanation:rule,example,translation,words,word:words[0].word,meaning:words[0].meaning,grammar,production,reading:{text:sceneText,questions:[meaningQ,detailQ]},audio:{text:`${example} ${u.story[0]}`,questions:[detailQ,meaningQ]},task:`Cuenta una situación propia relacionada con «${u.title}». Usa la idea de esta sesión, añade una razón y pregunta algo a la otra persona.`,focus:rule});
 });
 // Independent contextual reading/listening forms are authored per unit below.
});
export {syllabi};
